class UnexistingSerialNumber(Exception):
    """ Raised when device with given serial number couldn't be found in testline configuration file. """
    pass


class MissingPduPort(Exception):
    """ Raised when device has no PDU port specified in testline configuration file. """
    pass


class NoMatchingPdu(Exception):
    """ Raised when device has no matching PDU for it's port number in testline configuration file. """
    pass


class PduActionFailed(Exception):
    """ Raised when given PDU action cannot be done successfully. """
    pass
